import React, { useState, useRef, useEffect } from 'react';
import { getStylistAdvice } from '../services/geminiService';

const StylistAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'bot', text: string }[]>([
    { role: 'bot', text: "Bienvenida a JP Fashion. Soy tu estilista personal. ¿Buscas un look para una ocasión especial?" }
  ]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (isOpen) scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input;
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setInput("");
    setIsLoading(true);

    const advice = await getStylistAdvice(userMsg);
    setMessages(prev => [...prev, { role: 'bot', text: advice }]);
    setIsLoading(false);
  };

  return (
    <>
      {/* Trigger Button */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="fixed bottom-6 right-6 z-50 w-14 h-14 bg-gold rounded-full flex items-center justify-center shadow-2xl shadow-gold/20 hover:scale-110 transition-transform animate-pulse"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7 text-black" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
        </svg>
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-24 right-6 z-50 w-[90vw] sm:w-[350px] bg-black border border-gold/30 shadow-2xl overflow-hidden rounded-xl flex flex-col max-h-[500px]">
          <div className="p-4 bg-gold text-black font-bold flex justify-between items-center">
            <span className="uppercase tracking-widest text-xs">JP Stylist Assistant</span>
            <button onClick={() => setIsOpen(false)}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-[#0a0a0a]">
            {messages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] p-3 rounded-lg text-sm ${
                  m.role === 'user' 
                    ? 'bg-white/10 text-white' 
                    : 'bg-gold/10 text-gold border border-gold/20'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-gold/10 text-gold p-3 rounded-lg text-xs animate-pulse">
                  Escribiendo tendencias...
                </div>
              </div>
            )}
            <div ref={chatEndRef} />
          </div>

          <div className="p-3 border-t border-white/10 flex gap-2">
            <input 
              type="text" 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Pregúntale a tu estilista..."
              className="flex-1 bg-white/5 border border-white/10 rounded-full px-4 py-2 text-sm focus:outline-none focus:border-gold"
            />
            <button 
              onClick={handleSend}
              className="bg-gold text-black p-2 rounded-full hover:bg-white transition-colors"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
              </svg>
            </button>
          </div>
        </div>
      )}
    </>
  );
};

export default StylistAssistant;

import React from 'react';
import { CartItem } from '../types';

interface CartDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  items: CartItem[];
  onRemove: (id: number) => void;
}

const CartDrawer: React.FC<CartDrawerProps> = ({ isOpen, onClose, items, onRemove }) => {
  const total = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] overflow-hidden">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose}></div>
      <div className="absolute top-0 right-0 h-full w-full sm:w-[400px] bg-black border-l border-gold/30 shadow-2xl flex flex-col animate-slide-left">
        <div className="p-6 border-b border-white/10 flex justify-between items-center">
          <h2 className="text-xl font-serif">Tu Selección</h2>
          <button onClick={onClose} className="p-2 hover:text-gold">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {items.length === 0 ? (
            <div className="text-center py-20 text-gray-500">
              <p className="mb-4">Tu carrito está vacío.</p>
              <button onClick={onClose} className="text-gold uppercase tracking-widest text-xs font-bold border-b border-gold">Volver a la tienda</button>
            </div>
          ) : (
            items.map((item) => (
              <div key={item.id} className="flex gap-4">
                <img src={item.image} alt={item.name} className="w-20 h-24 object-cover border border-white/10" />
                <div className="flex-1">
                  <h3 className="text-sm font-serif">{item.name}</h3>
                  <p className="text-gold text-xs">${item.price.toFixed(2)}</p>
                  <div className="flex items-center justify-between mt-2">
                    <span className="text-[10px] text-gray-400">Cant: {item.quantity}</span>
                    <button 
                      onClick={() => onRemove(item.id)}
                      className="text-xs text-red-400 hover:text-red-300 transition-colors"
                    >
                      Eliminar
                    </button>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-[#0a0a0a] border-t border-white/10">
          <div className="flex justify-between mb-4">
            <span className="uppercase text-xs tracking-widest text-gray-400">Total estimado</span>
            <span className="text-lg font-bold">${total.toFixed(2)}</span>
          </div>
          <button 
            disabled={items.length === 0}
            className="w-full py-4 bg-gold text-black font-bold uppercase tracking-widest text-sm hover:bg-white transition-colors disabled:bg-gray-700 disabled:cursor-not-allowed"
          >
            Finalizar Compra
          </button>
          <p className="text-[10px] text-center text-gray-500 mt-4 uppercase tracking-tighter">
            Envío express gratuito en pedidos superiores a $500
          </p>
        </div>
      </div>
    </div>
  );
};

export default CartDrawer;

