            <ul className="space-y-4 text-xs text-gray-400 uppercase tracking-widest">
              <li><a href="#" className="hover:text-gold transition-colors">Inicio</a></li>
              <li><a href="#productos" className="hover:text-gold transition-colors">Colecciones</a></li>
