export const fetchFacebookProducts = async (): Promise<Product[]> => {
  // Simulamos un retraso de red
  await new Promise(resolve => setTimeout(resolve, 1500));

  // Estos datos representarían lo extraído de tu página: https://www.facebook.com/share/182dqtyq1v/
  // Cuando publiques algo nuevo, este array se alimentaría de la API de Meta.
  return [
