import React from 'react';
import { CartItem } from '../types';

interface CartDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  items: CartItem[];
  // Fix: id should be number | string to match Product.id type
  onRemove: (id: number | string) => void;
}

const CartDrawer: React.FC<CartDrawerProps> = ({ isOpen, onClose, items, onRemove }) => {
  // Fix: safely handle prices that are not numbers during reduction
  const total = items.reduce((sum, item) => {
    const price = typeof item.price === 'number' ? item.price : 0;
    return sum + (price * item.quantity);
  }, 0);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] overflow-hidden">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose}></div>
      <div className="absolute top-0 right-0 h-full w-full sm:w-[400px] bg-black border-l border-gold/30 shadow-2xl flex flex-col animate-slide-left">
        <div className="p-6 border-b border-white/10 flex justify-between items-center">
