          <button onClick={onClose} className="p-2 hover:text-gold">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {items.length === 0 ? (
            <div className="text-center py-20 text-gray-500">
              <p className="mb-4">Tu carrito está vacío.</p>
              <button onClick={onClose} className="text-gold uppercase tracking-widest text-xs font-bold border-b border-gold">Volver a la tienda</button>
            </div>
          ) : (
            items.map((item) => (
              <div key={item.id} className="flex gap-4">
                <img src={item.image} alt={item.name} className="w-20 h-24 object-cover border border-white/10" />
                <div className="flex-1">
                  <h3 className="text-sm font-serif">{item.name}</h3>
                  {/* Fix: safely handle toFixed for non-numeric prices */}
                  <p className="text-gold text-xs">
                    {typeof item.price === 'number' ? `$${item.price.toFixed(2)}` : 'Precio bajo consulta'}
                  </p>
                  <div className="flex items-center justify-between mt-2">
                    <span className="text-[10px] text-gray-400">Cant: {item.quantity}</span>
                    <button 
                      onClick={() => onRemove(item.id)}
                      className="text-xs text-red-400 hover:text-red-300 transition-colors"
                    >
                      Eliminar
                    </button>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-[#0a0a0a] border-t border-white/10">
          <div className="flex justify-between mb-4">
            <span className="uppercase text-xs tracking-widest text-gray-400">Total estimado</span>
            <span className="text-lg font-bold">${total.toFixed(2)}</span>
          </div>
          <button 
            disabled={items.length === 0}
