import { GoogleGenAI, Type } from "@google/genai";
import { Product } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const fetchFacebookProducts = async (pageUrl: string = "JP Fashion Facebook Boutique"): Promise<Product[]> => {
  try {
    const prompt = `Busca las últimas 3 o 4 publicaciones de venta de ropa en la página de Facebook "${pageUrl}". 
    Para cada publicación, extrae:
    1. Un nombre elegante para la prenda.
    2. El precio (si no hay, pon 'consultar').
    3. Una descripción corta y glamurosa.
    4. El enlace de la publicación.

    IMPORTANTE: Como no puedes darme la URL directa de la imagen de FB por restricciones, usa imágenes de Unsplash de alta calidad que representen ropa de mujer de lujo en colores negro, dorado o blanco que coincidan con la descripción.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              price: { type: Type.NUMBER }, // Opcional en el prompt pedimos 'consultar' pero el schema prefiere tipos fijos, manejaremos el fallback en el prompt
              description: { type: Type.STRING },
              category: { type: Type.STRING },
              image: { type: Type.STRING },
              link: { type: Type.STRING }
            },
            required: ["name", "description", "image", "link"]
          }
        }
      },
    });

    const results = JSON.parse(response.text || "[]");

    // Mapeamos a nuestro tipo Product
    return results.map((item: any, index: number) => ({
      id: `fb_extracted_${index}`,
      name: item.name,
      price: item.price || 'consultar',
      category: item.category || "Facebook Live",
      image: item.image,
      description: item.description,
      isSocial: true,
      link: item.link
    }));

  } catch (error) {
    console.error("Error extraiendo productos de FB:", error);
    // Fallback elegante en caso de error de API
    return [
      {
        id: 'fb_fallback_1',
        name: "Cargando Tendencias...",
