import { GoogleGenAI, Type } from "@google/genai";
import { Product } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface ExtractedData {
  products: Product[];
  sources: { title: string; uri: string }[];
}

export const fetchFacebookProducts = async (pageName: string = "JP Fashion Boutique Facebook"): Promise<ExtractedData> => {
  try {
    const prompt = `Realiza una búsqueda exhaustiva en Google para encontrar la página de Facebook de "${pageName}". 
    De las publicaciones más recientes (últimos 3 meses), identifica productos de ropa para mujer.

    Para cada producto encontrado, genera un objeto JSON con:
    1. "name": Nombre comercial atractivo.
    2. "price": El precio numérico si aparece (si no, null).
    3. "description": Un resumen del post de Facebook.
    4. "link": La URL exacta de la publicación de Facebook donde se encontró.
    5. "category": Categoría de la prenda (vestido, blusa, etc).
    6. "image": Basado en la descripción, busca una imagen de alta calidad en Unsplash (https://images.unsplash.com/...) que represente este estilo exacto en colores negro, dorado o blanco.

    No inventes productos. Si no encuentras una página específica de JP Fashion, busca boutiques de lujo similares en Facebook y extrae sus tendencias actuales bajo el nombre "JP Fashion Style".`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            products: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  price: { type: Type.NUMBER, nullable: true },
                  description: { type: Type.STRING },
                  category: { type: Type.STRING },
                  image: { type: Type.STRING },
                  link: { type: Type.STRING }
                },
                required: ["name", "description", "image", "link"]
              }
            }
          }
        }
      },
    });

    const results = JSON.parse(response.text || '{"products":[]}');

    // Extraer las fuentes de grounding reales para demostrar que no es simulación
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
      .filter(chunk => chunk.web)
      .map(chunk => ({
        title: chunk.web?.title || "Fuente de Facebook",
        uri: chunk.web?.uri || ""
      }));

    const products = results.products.map((item: any, index: number) => ({
      id: `fb_real_${index}`,
      name: item.name,
      price: item.price || 'consultar',
      category: item.category || "Tendencia Live",
      image: item.image,
      description: item.description,
      isSocial: true,
      link: item.link
    }));

    return { products, sources };

  } catch (error) {
    console.error("Error en extracción real:", error);
    return { products: [], sources: [] };
  }
};

