// CONFIGURACIÓN REAL DE META (Reemplazar con datos de tu App en developers.facebook.com)
const FACEBOOK_PAGE_ID = 'JPFashionBoutique'; // Tu ID de página o username
const ACCESS_TOKEN = ''; // Tu Page Access Token real

export interface FacebookPost {
  id: string;
  message?: string;
  full_picture?: string;
  permalink_url: string;
  created_time: string;
}

export const fetchFacebookProducts = async (): Promise<Product[]> => {
  // Si no hay token, el sistema no "simula", devuelve error o lista vacía para ser honesto
  if (!ACCESS_TOKEN) {
    console.warn("Facebook Access Token no configurado. Ve a developers.facebook.com");
    return [];
  }

  try {
    const response = await fetch(
      `https://graph.facebook.com/v18.0/${FACEBOOK_PAGE_ID}/posts?fields=message,full_picture,permalink_url,created_time&access_token=${ACCESS_TOKEN}`
    );

    const data = await response.json();

    if (data.error) {
      throw new Error(data.error.message);
    }

    // Mapeo técnico de los posts reales a objetos de producto
    return (data.data as FacebookPost[])
      .filter(post => post.full_picture) // Solo posts con imagen
      .map((post, index) => {
        // Extracción técnica de precio usando REGEX (sin IA)
        const priceMatch = post.message?.match(/\$\s?(\d+(?:\.\d{1,2})?)/);
        const price = priceMatch ? parseFloat(priceMatch[1]) : 'consultar';

        // El nombre es la primera línea del post
        const name = post.message?.split('\n')[0].substring(0, 40) || "Nueva Colección";

        return {
          id: post.id,
          name: name,
          price: price,
          category: "Facebook Post",
          image: post.full_picture!,
          description: post.message || "",
          isSocial: true,
          link: post.permalink_url
        };
      });
  } catch (error) {
    console.error("Error técnico extrayendo de Facebook API:", error);
    return [];
  }
};

