export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

export const fetchProductsFromDb = async (): Promise<Product[]> => {
  const { data, error } = await supabase
    .from('products')
    .select('*')
    .order('created_at', { ascending: false });

  if (error) {
    console.error("Error fetching products from Supabase:", error);
    return [];
  }

  return data.map(p => ({
    id: p.id,
    name: p.name,
    price: p.price,
    category: p.category,
    image: p.image,
    description: p.description,
    miniDescription: p.mini_description,
    sizes: p.sizes,
    fbId: p.fb_id // Mapeo del nuevo campo
  }));
};

export const fetchSocialProducts = async (): Promise<Product[]> => {
  const { data, error } = await supabase
    .from('products')
    .select('*')
    .not('fb_id', 'is', null) // Solo los que tienen ID de Facebook
    .order('created_at', { ascending: false })
    .limit(8);

  if (error) {
    console.error("Error fetching social products:", error);
    return [];
  }

  return data.map(p => ({
    id: p.id,
    name: p.name,
    price: p.price,
    category: p.category,
    image: p.image,
    description: p.description,
    miniDescription: p.mini_description,
    sizes: p.sizes,
    fbId: p.fb_id,
    isSocial: true,
    link: `https://facebook.com/${p.fb_id}` // Link dinámico a Facebook
  }));
};

export const fetchCategoriesFromDb = async (): Promise<Category[]> => {
  const { data, error } = await supabase
    .from('categories')
    .select('*')
    .order('name');

  if (error) {
    console.error("Error fetching categories from Supabase:", error);
    return [];
  }

  return data;
};

