import React, { useState, useEffect } from 'react';
import { Product } from '../types';

interface ProductCardProps {
  product: Product;
  onAddToCart: (product: Product & { selectedSize?: string }) => void;
}

const ProductCard: React.FC<ProductCardProps> = ({ product, onAddToCart }) => {
  // Inicializar con la primera talla disponible si existe
  const [selectedSize, setSelectedSize] = useState<string | undefined>(undefined);

  useEffect(() => {
    if (product.sizes && product.sizes.length > 0) {
      setSelectedSize(product.sizes[0]);
    }
  }, [product.sizes]);

  return (
    <div className="group relative bg-[#0a0a0a] border border-white/5 overflow-hidden transition-all duration-500 hover:border-gold/30 flex flex-col h-full shadow-lg hover:shadow-gold/5">
      <div className="aspect-[3/4] overflow-hidden relative">
        <img 
          src={product.image} 
          alt={product.name} 
          className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110 grayscale-[20%] group-hover:grayscale-0"
        />

        {/* Hover Overlay: Selección de Talla e Interacción */}
        <div className="absolute inset-0 bg-black/70 opacity-0 group-hover:opacity-100 transition-all duration-500 flex flex-col items-center justify-center p-6 text-center transform translate-y-4 group-hover:translate-y-0">
          {product.sizes && product.sizes.length > 0 ? (
            <div className="mb-8 w-full">
              <p className="text-[10px] text-gold uppercase tracking-[0.4em] mb-4 font-bold">Seleccionar Talla</p>
              <div className="flex flex-wrap justify-center gap-3">
                {product.sizes.map(size => (
                  <button
                    key={size}
                    onClick={(e) => {
                      e.stopPropagation();
                      setSelectedSize(size);
                    }}
                    className={`w-10 h-10 text-[10px] border flex items-center justify-center transition-all duration-300 rounded-sm ${
                      selectedSize === size 
                        ? 'bg-gold border-gold text-black font-bold scale-110 shadow-lg shadow-gold/20' 
                        : 'border-white/20 text-white hover:border-gold hover:text-gold'
                    }`}
                  >
                    {size}
                  </button>
                ))}
              </div>
            </div>
          ) : (
            <p className="text-[9px] text-gray-400 uppercase tracking-widest mb-6 italic">Talla única disponible</p>
          )}

          <button 
            onClick={() => onAddToCart({ ...product, selectedSize })}
            className="bg-white text-black w-full py-4 font-bold uppercase tracking-[0.2em] text-[10px] hover:bg-gold transition-all duration-300 transform active:scale-95 shadow-xl"
          >
            Añadir al Carrito
          </button>
        </div>
      </div>

      <div className="p-6 text-center flex-1 flex flex-col">
        <p className="text-[8px] text-gold uppercase tracking-[0.4em] mb-3 font-bold opacity-70">{product.category}</p>
        <h3 className="text-lg font-serif mb-2 group-hover:text-gold transition-colors duration-300">{product.name}</h3>

        {product.miniDescription && (
          <p className="text-[11px] text-gray-500 font-light italic mb-4 line-clamp-1 opacity-80">
            "{product.miniDescription}"
          </p>
        )}

        <div className="mt-auto pt-4 border-t border-white/5">
          <p className="text-white font-medium tracking-[0.1em] text-sm">
            {typeof product.price === 'number' ? `$${product.price.toLocaleString('en-US', { minimumFractionDigits: 2 })}` : 'Consultar'}
          </p>
          {selectedSize && (
            <div className="flex items-center justify-center gap-2 mt-2">
              <span className="w-1 h-1 bg-gold rounded-full"></span>
              <p className="text-[9px] text-gray-600 uppercase tracking-[0.2em]">
                Talla Actual: <span className="text-white font-bold">{selectedSize}</span>
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProductCard;

import React from 'react';
import { CartItem } from '../types';

interface CartDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  items: CartItem[];
  onRemove: (id: number | string, size?: string) => void;
}

const CartDrawer: React.FC<CartDrawerProps> = ({ isOpen, onClose, items, onRemove }) => {
  const total = items.reduce((sum, item) => {
    const price = typeof item.price === 'number' ? item.price : 0;
    return sum + (price * item.quantity);
